const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isDec = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'
const isAlpha = (c) => c !== undefined && /^[A-Za-z_]$/.test(c)
const isIdent = (c) => isAlpha(c) || isDec(c)

class Fail {
  constructor(line, col, reason) { this.line = line; this.col = col; this.reason = reason }
}

export function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

  try {
    while (i < n) {
      const c = s[i]
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
      if (c === '/' && s[i + 1] === '/') {
        while (i < n && s[i] !== '\n') adv()
        continue
      }
      if (c === '/' && s[i + 1] === '*') {
        const l0 = line, c0 = col
        let depth = 0
        do {
          if (i >= n) throw new Fail(l0, c0, 'unterminated block comment')
          if (s[i] === '/' && s[i + 1] === '*') { adv(); adv(); depth++ }
          else if (s[i] === '*' && s[i + 1] === '/') { adv(); adv(); depth-- }
          else adv()
        } while (depth > 0)
        continue
      }
      const l0 = line, c0 = col
      const push = (kind, body) => tokens.push({ line: l0, col: c0, kind, body })

      if (c === 'r' && s[i + 1] === '"') {
        adv(); adv()
        let v = ''
        while (true) {
          if (i >= n) throw new Fail(l0, c0, 'unterminated string')
          const d = adv()
          if (d === '"') break
          v += d
        }
        push('rawstring', JSON.stringify(v))
        continue
      }
      if (isAlpha(c)) {
        let w = ''
        while (i < n && isIdent(s[i])) w += adv()
        push(KEYWORDS.has(w) ? 'keyword' : 'ident', w)
        continue
      }
      if (isDec(c)) {
        let w = ''
        const run = (isD) => {
          let got = false
          while (i < n) {
            if (isD(s[i])) { w += adv(); got = true }
            else if (s[i] === '_' && got && isD(s[i + 1]) && isD(s[i - 1])) w += adv()
            else break
          }
          return got
        }
        let ok = true
        const p = s[i + 1]
        if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
          w += adv(); w += adv()
          const f = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? isBin : isOct
          ok = run(f)
        } else {
          run(isDec)
          if (s[i] === '.' && isDec(s[i + 1])) { w += adv(); run(isDec) }
          if (s[i] === 'e' || s[i] === 'E') {
            if (isDec(s[i + 1]) || ((s[i + 1] === '+' || s[i + 1] === '-') && isDec(s[i + 2]))) {
              w += adv()
              if (!isDec(s[i])) w += adv()
              run(isDec)
            }
          }
        }
        if (!ok || isIdent(s[i])) {
          while (i < n && isIdent(s[i])) w += adv()
          throw new Fail(l0, c0, `invalid number ${w}`)
        }
        push('number', w)
        continue
      }
      if (c === '"') {
        adv()
        let v = ''
        while (true) {
          if (i >= n) throw new Fail(l0, c0, 'unterminated string')
          const bl = line, bc = col
          const d = adv()
          if (d === '"') break
          if (d === '\n') throw new Fail(bl, bc, 'newline in string')
          if (d !== '\\') { v += d; continue }
          if (i >= n) throw new Fail(l0, c0, 'unterminated string')
          const e = adv()
          const bad = () => new Fail(bl, bc, `invalid escape \\${e}`)
          if (e === 'n') v += '\n'
          else if (e === 't') v += '\t'
          else if (e === 'r') v += '\r'
          else if (e === '\\') v += '\\'
          else if (e === '"') v += '"'
          else if (e === '0') v += '\0'
          else if (e === 'x') {
            if (!isHex(s[i]) || !isHex(s[i + 1])) throw bad()
            v += String.fromCharCode(parseInt(s[i] + s[i + 1], 16)); adv(); adv()
          } else if (e === 'u') {
            if (s[i] !== '{') throw bad()
            let j = i + 1, h = ''
            while (isHex(s[j])) h += s[j++]
            if (!h || s[j] !== '}') throw bad()
            const cp = parseInt(h, 16)
            if (cp > 0x10ffff) throw bad()
            v += String.fromCodePoint(cp)
            while (i <= j) adv()
          } else throw bad()
        }
        push('string', JSON.stringify(v))
        continue
      }
      const two = c + (s[i + 1] ?? '')
      if (PUNCT2.has(two)) { adv(); adv(); push('punct', two); continue }
      if (PUNCT1.has(c)) { adv(); push('punct', c); continue }
      throw new Fail(l0, c0, `unexpected character ${c}`)
    }
  } catch (e) {
    if (e instanceof Fail) return { error: e }
    throw e
  }
  return { tokens }
}
